const crypto = require('node:crypto')
const { configuredRoutes } = require('./control-bound-protocol')
const { compileNativeBindingPlan } = require('./native-binding-plan')
const { managedBridgeRevision } = require('./managed-bridge-revision')

const MARKER = 'control-panel-managed-v1'

function digest (value) {
  return crypto.createHash('sha256').update(JSON.stringify(value)).digest('hex')
}

function panelTargets (panel) {
  const targets = new Map()
  for (const [id, { control, binding }] of configuredRoutes(panel)) {
    if (!binding?.device) throw new Error(`Missing device binding: ${id}`)
    for (const direction of ['read', 'write']) {
      if ((direction === 'read' && control.mode === 'write') ||
        (direction === 'write' && control.mode === 'read')) continue
      const path = binding[`${direction}Path`]
      const meta = binding[`${direction}Meta`]
      if (!path || !meta || typeof meta !== 'object' || Array.isArray(meta)) {
        throw new Error(`Missing ${direction} target metadata: ${id}`)
      }
      const target = {
        device: binding.device, path, kind: meta.kind, type: meta.type,
        access: meta.access, onebased: meta.onebased,
        min: meta.min, max: meta.max, enums: meta.enums,
        ...(meta.booleanEncoding ? { booleanEncoding: meta.booleanEncoding } : {}),
        ...(meta.meter ? { meter: meta.meter } : {}),
        ...(meta.xySeries ? { xySeries: meta.xySeries } : {}),
        ...(meta.availability ? { availability: meta.availability } : {})
      }
      const key = JSON.stringify([target.device, target.path])
      const previous = targets.get(key)
      if (previous && digest(previous) !== digest(target)) {
        throw new Error(`Conflicting target metadata: ${target.device} ${target.path}`)
      }
      targets.set(key, target)
    }
  }
  return [...targets.values()]
}

function generatedBridge (panel) {
  const scopeId = `cp${digest(panel.id).slice(0, 12)}`
  const { nodes, manifest } = compileNativeBindingPlan({ panel, targets: panelTargets(panel), scopeId })
  const subflow = nodes[0]
  subflow.info = `${MARKER}:${panel.id}:${digest(nodes.slice(1))}`
  const instanceId = `${scopeId}-instance`
  const instance = {
    id: instanceId,
    type: `subflow:${manifest.subflowId}`,
    z: panel.z,
    name: `Managed bridge for ${panel.id}`,
    x: Number(panel.x || 200) + 240,
    y: Number(panel.y || 200),
    wires: manifest.nativeReads ? [[panel.id]] : []
  }
  return { nodes, instance, manifest, scopeId }
}

function removeBridgeNodes (flows, subflowId, instanceId) {
  const removeIds = new Set([subflowId, instanceId])
  for (const node of flows) {
    if (node.z === subflowId || node.type === `subflow:${subflowId}`) {
      removeIds.add(node.id)
    }
  }

  // Remove references from any remaining node before the generated bridge is
  // replaced. The panel itself is assigned its new wire immediately after.
  for (const node of flows) {
    if (removeIds.has(node.id) || !Array.isArray(node.wires)) continue
    node.wires = node.wires.map(port => Array.isArray(port)
      ? port.filter(id => !removeIds.has(id))
      : port)
  }

  for (let index = flows.length - 1; index >= 0; index--) {
    if (removeIds.has(flows[index].id)) flows.splice(index, 1)
  }
}

function provisionManagedBridges (currentFlows, options = {}) {
  if (!Array.isArray(currentFlows)) throw new Error('Expected a Node-RED Flow array')
  const flows = structuredClone(currentFlows)
  const scopedPanelId = options.panelId || null
  const owners = flows.filter(node => node.type === 'ui-control-panel' && node.nativeBridge === true &&
    (!scopedPanelId || node.id === scopedPanelId))
  const updated = []
  for (const panel of owners) {
    if (!panel.id || !panel.z) throw new Error('Managed panel needs an ID and Flow tab')
    const bridge = generatedBridge(panel)
    const revision = managedBridgeRevision(panel)
    const { nodes, instance, manifest, scopeId } = bridge
    const subflowId = manifest.subflowId
    const previous = flows.find(node => node.id === instance.id)
    const generatedIds = new Set(nodes.map(node => node.id))
    if (instance.wires[0]) {
      for (const id of previous?.wires?.[0] || []) {
        if (id !== panel.id && !generatedIds.has(id) && flows.some(node => node.id === id) &&
          !instance.wires[0].includes(id)) instance.wires[0].push(id)
      }
    }
    for (const event of nodes.filter(node => node.type === 'Event')) {
      const old = flows.find(node => node.id === event.id && node.type === 'Event')
      if (old?.cpSubscriptionEpoch && digest(old.mojo) === digest(event.mojo)) {
        event.cpSubscriptionEpoch = old.cpSubscriptionEpoch
      }
    }
    nodes[0].info = `${MARKER}:${panel.id}:${digest(nodes.slice(1))}`

    // The bridge is derived state. Always remove the complete previous
    // generation for this panel, including moved or older-version nodes.
    removeBridgeNodes(flows, subflowId, instance.id)
    panel.wires = [[instance.id]]
    panel.bridgeRevisionApplied = revision
    flows.push(...nodes, instance)
    updated.push({ panelId: panel.id, room: panel.boundRoom, controls: manifest.controls,
      reads: manifest.nativeReads, writes: manifest.nativeWrites, scopeId })
  }
  for (const subflow of [...flows]) {
    if (subflow.type !== 'subflow' || typeof subflow.info !== 'string' ||
      !subflow.info.startsWith(`${MARKER}:`)) continue
    const match = subflow.info.match(/^control-panel-managed-v1:([^:]+):([a-f0-9]{64})$/)
    if (!match) continue
    const ownerId = match[1]
    if (scopedPanelId && ownerId !== scopedPanelId) continue
    if (owners.some(panel => panel.id === ownerId)) continue
    const scopeId = `cp${digest(ownerId).slice(0, 12)}`
    const instanceId = `${scopeId}-instance`
    const oldPanel = flows.find(node => node.id === ownerId)
    if (oldPanel) {
      oldPanel.wires = [[]]
      oldPanel.bridgeRevisionApplied = ''
    }
    removeBridgeNodes(flows, subflow.id, instanceId)
    updated.push({ panelId: ownerId, removed: true })
  }
  return { flows, updated, managedPanels: owners.length }
}

function refreshManagedSubscriptions (currentFlows, { panelId, device, epoch }) {
  if (typeof epoch !== 'string' || !epoch || epoch.length > 128) throw Error('Invalid subscription epoch')
  const flows = structuredClone(currentFlows)
  const panel = flows.find(node => node.id === panelId && node.type === 'ui-control-panel' && node.nativeBridge === true)
  if (!panel) return null
  const expected = generatedBridge(panel)
  const subflow = flows.find(node => node.id === expected.nodes[0].id &&
    node.info?.startsWith(`${MARKER}:${panelId}:`))
  if (!subflow || panel.bridgeRevisionApplied !== managedBridgeRevision(panel)) return null
  let changed = false
  for (const node of expected.nodes.filter(node => node.type === 'Event' && node.mojo.device.includes(device))) {
    const existing = flows.find(old => old.id === node.id && old.z === subflow.id && old.type === 'Event')
    if (!existing || digest(existing.mojo) !== digest(node.mojo)) return null
    if (existing.cpSubscriptionEpoch !== epoch) { existing.cpSubscriptionEpoch = epoch; changed = true }
  }
  if (!changed) return null
  subflow.info = `${MARKER}:${panelId}:${digest(flows.filter(node => node.z === subflow.id))}`
  return flows
}

module.exports = { panelTargets, generatedBridge, provisionManagedBridges, refreshManagedSubscriptions }
